select 'sql_functions_that_update_jobs_status=' || count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname in ('public', 'private') and p.prosrc ~* '(update\s+public\.jobs|update\s+jobs)[^;]*status';
select 'of_which_executable_by_anon_or_authenticated=' || count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname in ('public', 'private') and p.prosrc ~* '(update\s+public\.jobs|update\s+jobs)[^;]*status' and (has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute'));
select 'authenticated_table_privileges_on_jobs=' || coalesce(string_agg(privilege_type, ',' order by privilege_type), 'none') from information_schema.role_table_grants where table_schema = 'public' and table_name = 'jobs' and grantee = 'authenticated';
select 'anon_table_privileges_on_jobs=' || coalesce(string_agg(privilege_type, ',' order by privilege_type), 'none') from information_schema.role_table_grants where table_schema = 'public' and table_name = 'jobs' and grantee = 'anon';
select 'functions_that_set_status_reviewed=' || coalesce(string_agg(n.nspname || '.' || p.proname, ',' order by n.nspname, p.proname), 'none') from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname in ('public', 'private') and p.prosrc ~* 'status\s*=\s*''reviewed''';
select 'reviewed_writers_executable_by_api_roles=' || count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname in ('public', 'private') and p.prosrc ~* 'status\s*=\s*''reviewed''' and (has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute'));
select 'sepay_webhook_function_present=' || exists (select 1 from pg_proc where proname = 'apply_sepay_vietqr_payment_webhook');
